"""Generate one public Rust convenience function for each shader operation."""
from pathlib import Path
from collections import Counter
import re,runpy
root=Path(__file__).resolve().parent.parent
ops=runpy.run_path(str(root/'tools/generate_catalog.py'))['ops']

def snake(name):
    s=re.sub(r'([A-Z]+)([A-Z][a-z])',r'\1_\2',name)
    s=re.sub(r'([a-z0-9])([A-Z])',r'\1_\2',s)
    return s.lower()

lines=['//! One Rust function per catalogued GPU operation. All operate on shader source, not a GPU.',
       '//! Generated by `python3 tools/generate_wrappers.py` and compiled normally by Cargo.',
       'use crate::{Emitter, Expr, Error, Intrinsic, Type};','']
seen=[]
for name,family,sig,lo,hi,cap,stage,wgsl,glsl,hlsl,intel in ops:
    function=snake(name)
    assert function not in seen,function
    seen.append(function)
    native=', '.join(a for a,b in [('WGSL',wgsl),('GLSL',glsl),('HLSL',hlsl),('Intel OpenCL',intel)] + ([('NVIDIA CUDA',name)] if name.startswith('Nvidia') else []) if b)
    desc=f'Emit `{name}` ({family} family; {lo}–{hi} arguments).'
    lines.append(f'/// {desc}')
    lines.append(f'/// Shader targets with a native mapping: {native or "none (metadata only)"}.')
    lines.append('/// Returns an error when the selected backend, stage, feature or argument signature is unsupported.')
    lines.append('#[inline]')
    if sig=='Special' and name!='Select':
        lines.append(f'pub fn {function}(emitter:&Emitter,args:&[Expr],return_ty:Type)->Result<Expr,Error>{{')
        lines.append(f'    emitter.call_typed(Intrinsic::{name},args,return_ty)')
    elif sig=='Barrier':
        lines.append(f'pub fn {function}(emitter:&Emitter)->Result<Expr,Error>{{')
        lines.append(f'    emitter.call(Intrinsic::{name},&[])')
    else:
        lines.append(f'pub fn {function}(emitter:&Emitter,args:&[Expr])->Result<Expr,Error>{{')
        lines.append(f'    emitter.call(Intrinsic::{name},args)')
    lines.extend(['}',''])
(root/'src/ops.rs').write_text('\n'.join(lines),encoding='utf-8')
print('Generated',len(seen),'documented Rust intrinsic wrappers; names unique')
